/**
 * Upload API — Presigned URL generation for sandbox file uploads.
 *
 * Following the Manus pattern: code running inside E2B sandboxes calls this
 * endpoint to get a presigned S3 PUT URL, then uploads directly to S3.
 * The orchestrator NEVER receives the file bytes — the sandbox uploads directly.
 *
 * Endpoints:
 *   POST /api/upload/presign — Generate presigned PUT URL + CDN URL
 *
 * Auth: Bearer token in Authorization header — must be a valid sandbox proxy token
 * (sk-rubic-<random>) generated by the orchestrator when creating a sandbox.
 *
 * Flow:
 *   1. rubic-upload-file (in sandbox) → POST /api/upload/presign { filename, contentType }
 *   2. Orchestrator validates token → generates presigned PUT URL + CDN URL
 *   3. rubic-upload-file → PUT <presigned-url> with file bytes (direct to S3)
 *   4. rubic-upload-file → prints CDN URL to stdout
 */

import type { FastifyInstance } from "fastify";
import crypto from "node:crypto";
import path from "node:path";
import { createLogger } from "@repo/service-utils";
import { validateProxyToken } from "../lib/e2b-manager.js";

const logger = createLogger({ service: "upload" });

// Lazy-load storage to avoid import errors when S3 is not configured
let _storage: typeof import("@repo/storage") | null = null;
async function getStorage(): Promise<typeof import("@repo/storage")> {
  if (!_storage) {
    const mod = await import("@repo/storage");
    // eslint-disable-next-line @typescript-eslint/no-explicit-any -- ESM default export workaround
    _storage = (mod as any).default ?? mod;
  }
  return _storage!;
}

/** Common MIME type mappings for files without explicit content type */
const EXT_MIME_MAP: Record<string, string> = {
  ".png": "image/png",
  ".jpg": "image/jpeg",
  ".jpeg": "image/jpeg",
  ".gif": "image/gif",
  ".webp": "image/webp",
  ".svg": "image/svg+xml",
  ".pdf": "application/pdf",
  ".mp4": "video/mp4",
  ".webm": "video/webm",
  ".mp3": "audio/mpeg",
  ".wav": "audio/wav",
  ".txt": "text/plain",
  ".html": "text/html",
  ".css": "text/css",
  ".js": "application/javascript",
  ".json": "application/json",
  ".zip": "application/zip",
  ".tar": "application/x-tar",
  ".gz": "application/gzip",
};

function guessMimeType(filename: string): string {
  const ext = path.extname(filename).toLowerCase();
  return EXT_MIME_MAP[ext] || "application/octet-stream";
}

function extractBearerToken(authHeader: string | undefined): string | null {
  if (!authHeader) return null;
  const parts = authHeader.split(" ");
  if (parts.length !== 2 || parts[0] !== "Bearer") return null;
  return parts[1] || null;
}

/** Extract token from either Authorization header or x-sandbox-token fallback */
function extractToken(request: { headers: Record<string, string | string[] | undefined> }): string | null {
  const bearer = extractBearerToken(request.headers.authorization as string | undefined);
  if (bearer) return bearer;
  // Fallback: x-sandbox-token header (backward compat with older rubic-upload-file)
  const sandboxToken = request.headers["x-sandbox-token"];
  if (typeof sandboxToken === "string" && sandboxToken) return sandboxToken;
  return null;
}

export async function uploadRoutes(app: FastifyInstance) {
  // ─── POST /api/upload/presign ──────────────────────────────────────────
  // Returns a presigned PUT URL for direct S3 upload + the final CDN/access URL.
  app.post("/api/upload/presign", async (request, reply) => {
    // Validate auth — supports Authorization: Bearer <token> and x-sandbox-token fallback
    const token = extractToken(request);
    if (!token) {
      return reply.status(401).send({
        error: {
          message: "Missing or invalid Authorization header. Expected: Bearer <token>",
          type: "invalid_request_error",
          code: "invalid_api_key",
        },
      });
    }

    const tokenInfo = validateProxyToken(token);
    if (!tokenInfo) {
      logger.warn({ tokenPrefix: token.substring(0, 12) }, "Upload: invalid proxy token");
      return reply.status(401).send({
        error: {
          message: "Invalid API key. The provided sandbox proxy token is not recognized.",
          type: "invalid_request_error",
          code: "invalid_api_key",
        },
      });
    }

    const body = request.body as Record<string, unknown>;
    const filename = body.filename as string | undefined;

    if (!filename || typeof filename !== "string") {
      return reply.status(400).send({
        error: {
          message: "Missing required field: filename",
          type: "invalid_request_error",
          code: "missing_field",
        },
      });
    }

    // Determine content type
    const contentType = (body.contentType as string) || guessMimeType(filename);

    // Generate unique S3 key (Manus pattern: random ID + original extension)
    const randomId = crypto.randomBytes(12).toString("base64url");
    const ext = path.extname(filename);
    const sanitizedName = path.basename(filename, ext).replace(/[^a-zA-Z0-9_-]/g, "_");
    const s3Key = `uploads/${tokenInfo.userId}/session/${tokenInfo.sessionId}/${randomId}_${sanitizedName}${ext}`;

    try {
      const storage = await getStorage();

      // Generate presigned PUT URL (1 hour expiry)
      const uploadUrl = await storage.getPresignedUploadUrl(s3Key, contentType, 3600);

      // Generate access URL (CDN preferred, falls back to presigned GET)
      const accessUrl = storage.getCdnUrl(s3Key) || await storage.getPresignedUrl(s3Key, 86400, true);

      logger.info(
        {
          filename,
          contentType,
          s3Key,
          sandboxId: tokenInfo.sandboxId,
          userId: tokenInfo.userId,
        },
        "Upload: presigned URL generated"
      );

      return reply.send({
        uploadUrl,
        accessUrl,
        s3Key,
        contentType,
        expiresIn: 3600,
      });
    } catch (error) {
      const errMsg = error instanceof Error ? error.message : "Unknown error";
      logger.error({ error: errMsg }, "Upload: failed to generate presigned URL");

      return reply.status(500).send({
        error: {
          message: `Failed to generate presigned URL: ${errMsg}`,
          type: "server_error",
          code: "presign_failed",
        },
      });
    }
  });

  // ─── Health check ──────────────────────────────────────────────────────
  app.get("/api/upload/health", async (_request, reply) => {
    let s3Configured = false;
    try {
      const storage = await getStorage();
      s3Configured = !!storage.getStorageConfig().bucket;
    } catch {
      // S3 not configured
    }

    return reply.send({
      status: s3Configured ? "ok" : "degraded",
      s3Configured,
    });
  });
}
